package org.sleepwell.app;

import android.app.Activity;
import android.os.*;
import android.text.InputType;
import android.view.Gravity;
import android.widget.*;
import java.util.*;

/** Screen 33: real saved rules; opening/configuring never sends an event. */
public final class AutomationActivity extends Activity {
    private final Handler handler=new Handler(Looper.getMainLooper());
    private long generation;private boolean busy;private String failure="";private AutomationRule draft;
    private EditText name,destination,topic,username,secret;private Switch enabled;
    @Override public void onCreate(Bundle state){super.onCreate(state);if(getIntent().getBooleanExtra("visualReview",false))getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(state!=null&&state.containsKey("id")){draft=new AutomationRule(state.getString("id"),state.getString("name",""),AutomationEvent.Kind.valueOf(state.getString("event")),AutomationRule.Transport.valueOf(state.getString("transport")),state.getBoolean("enabled"),state.getLong("revision"),state.getString("destination",""),state.getString("topic",""),state.getString("username",""),"");try{String cipher=state.getString("secret","");if(!cipher.isEmpty())draft=new AutomationRule(draft.id,draft.name,draft.event,draft.transport,draft.enabled,draft.revision,draft.destination,draft.topic,draft.username,new AutomationSecrets().open(cipher));}catch(Exception e){failure="Re-enter the destination credential before saving.";}editor();}else list();Automations.recover(this);}
    @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(draft!=null){readFields();state.putString("id",draft.id);state.putString("name",draft.name);state.putString("event",draft.event.name());state.putString("transport",draft.transport.name());state.putBoolean("enabled",draft.enabled);state.putLong("revision",draft.revision);state.putString("destination",draft.destination);state.putString("topic",draft.topic);state.putString("username",draft.username);try{state.putString("secret",new AutomationSecrets().seal(draft.secret));}catch(Exception ignored){}}}
    private void list(){draft=null;long ticket=++generation;LinearLayout body=Design.page(this,false,null,n->{});Design.header(body,"Automations",this::finish);Design.text(body,"Trigger actions from sleep events",14,400,Design.MUTED);Design.space(body,20);Design.text(body,"Your rules",18,600,Design.INK);Design.space(body,8);LinearLayout rules=Design.col(this);body.addView(rules);Design.text(rules,"Loading rules…",13,400,Design.MUTED);if(!failure.isEmpty()){Design.text(body,failure,13,500,Design.BROWN);failure="";}Design.button(body,"Add rule",false,()->{draft=new AutomationRule(UUID.randomUUID().toString(),"",AutomationEvent.Kind.TRACKING_STARTED,AutomationRule.Transport.INTENT,false,0,"net.dinglisch.android.taskerm","","","");editor();});Design.space(body,16);Design.text(body,"Destinations",16,600,Design.INK);Design.text(body,"Tasker / receiving app · HTTPS webhook · MQTT over TLS",13,400,Design.MUTED);Design.space(body,12);Design.text(body,"Events share only type, time and an anonymous event ID. Rules are off until you enable them.",12,400,Design.MUTED);Automations.io.execute(()->{List<AutomationStore.Row> rows;String issue;try(AutomationStore store=new AutomationStore(this)){rows=store.rows();issue=getSharedPreferences("automation_status",0).getString("error","");}catch(Exception e){rows=List.of();issue="Rules could not be loaded. Reopen Automations to retry.";}List<AutomationStore.Row> loaded=rows;String error=issue;handler.post(()->{if(isDestroyed()||ticket!=generation)return;rules.removeAllViews();if(!error.isEmpty())Design.text(rules,error,13,500,Design.BROWN);if(loaded.isEmpty())Design.text(rules,"No rules yet",14,400,Design.MUTED);for(AutomationStore.Row row:loaded){LinearLayout card=Design.col(this);Design.pad(card,14,12);card.setBackground(Design.shape(this,Design.SOFT,16));PlanActivity.detail(card,row.transport.equals("INTENT")?"settings":"link",row.name,eventLabel(AutomationEvent.Kind.valueOf(row.event)),null,()->load(row.id));Design.toggle(card,"Enabled",row.status,row.enabled,on->setEnabled(row,on));rules.addView(card);Design.space(rules,10);}});});}
    private void load(String id){if(busy)return;busy=true;Automations.io.execute(()->{AutomationRule loaded=null;try(AutomationStore store=new AutomationStore(this)){loaded=store.rule(id);}catch(Exception ignored){}AutomationRule result=loaded;handler.post(()->{busy=false;if(isDestroyed())return;if(result==null){new android.app.AlertDialog.Builder(this).setTitle("Destination unavailable").setMessage("The saved destination could not be opened. Your sleep records are unaffected. Delete this rule to enter it again.").setNegativeButton("Keep rule",null).setPositiveButton("Delete rule",(d,w)->Automations.io.execute(()->{try(AutomationStore store=new AutomationStore(this)){store.delete(id);Automations.schedule(this,store);}handler.post(()->{if(!isDestroyed())list();});})).show();return;}draft=result;editor();});});}
    private void setEnabled(AutomationStore.Row row,boolean value){Automations.io.execute(()->{String issue="";try(AutomationStore store=new AutomationStore(this)){store.enabled(row.id,row.revision,value);Automations.schedule(this,store);}catch(Exception e){issue="Rule could not change. Refresh and retry.";}String error=issue;handler.post(()->{if(isDestroyed()||draft!=null)return;failure=error;list();});});}
    private void editor(){if(draft==null)return;generation++;LinearLayout body=Design.page(this,false,null,n->{});Design.header(body,draft.revision==0?"Add rule":"Edit rule",()->{if(!busy)list();});name=field(body,"Rule name",draft.name,false);PlanActivity.detail(body,"moon","When",null,eventLabel(draft.event),()->{readFields();String[] labels=Arrays.stream(AutomationEvent.Kind.values()).map(AutomationActivity::eventLabel).toArray(String[]::new);SleepPicker.choices(this,"Sleep event",labels,draft.event.ordinal(),index->{draft=new AutomationRule(draft.id,draft.name,AutomationEvent.Kind.values()[index],draft.transport,draft.enabled,draft.revision,draft.destination,draft.topic,draft.username,draft.secret);editor();});});PlanActivity.detail(body,"link","Destination type",null,transportLabel(draft.transport),()->{readFields();SleepPicker.choices(this,"Destination type",new String[]{"Tasker / app broadcast","HTTPS webhook","MQTT over TLS"},draft.transport.ordinal(),index->{AutomationRule.Transport choice=AutomationRule.Transport.values()[index];draft=new AutomationRule(draft.id,draft.name,draft.event,choice,draft.enabled,draft.revision,choice==AutomationRule.Transport.INTENT?"net.dinglisch.android.taskerm":"","","","");editor();});});
        destination=field(body,draft.transport==AutomationRule.Transport.INTENT?"Receiving app package":draft.transport==AutomationRule.Transport.WEBHOOK?"HTTPS URL":"Broker: ssl://host:8883",draft.destination,false);topic=null;username=null;secret=null;
        if(draft.transport==AutomationRule.Transport.INTENT){Design.text(body,"Tasker profile: Event → System → Intent Received",12,400,Design.MUTED);Design.space(body,5);TextView action=Design.text(body,"org.sleepwell.app.event."+draft.event.name(),12,500,Design.BROWN);action.setTextIsSelectable(true);Design.text(body,"Extras: event_id, event, occurred_at, test, schema. The receiving profile must be active.",12,400,Design.MUTED);}else{if(draft.transport==AutomationRule.Transport.MQTT){topic=field(body,"Publish topic",draft.topic,false);username=field(body,"Username (optional)",draft.username,false);}secret=field(body,draft.transport==AutomationRule.Transport.WEBHOOK?"Bearer token (optional)":"Password (optional)",draft.secret,true);Design.text(body,draft.transport==AutomationRule.Transport.MQTT?"TLS certificate verification · non-retained QoS 1 publish":"HTTPS POST · redirects are rejected",12,400,Design.MUTED);}
        enabled=Design.toggle(body,"Enabled","New events only; editing cancels queued attempts.",draft.enabled,on->{});if(!failure.isEmpty()){Design.space(body,8);Design.text(body,failure,13,500,Design.BROWN);}Design.space(body,10);Design.text(body,"Up to 6 attempts in 24 hours. Delivery may be delayed by Android. An in-flight request cannot be recalled.",12,400,Design.MUTED);LinearLayout footer=RecordUi.footer(body);Design.button(footer,busy?"Saving…":"Save rule",true,this::save).setEnabled(!busy);if(draft.revision>0){Design.button(footer,"Send test event",false,this::test).setEnabled(!busy);Design.button(footer,"Delete rule",false,this::delete).setEnabled(!busy);}if(busy)RecordUi.enabled(body,false);
    }
    private EditText field(LinearLayout body,String title,String value,boolean password){Design.space(body,10);Design.text(body,title,13,500,Design.INK);EditText field=new EditText(this);field.setSingleLine(true);field.setTextSize(15);field.setTypeface(Design.font(this,400));field.setTextColor(Design.INK);field.setBackground(Design.shape(this,Design.SOFT,12));field.setPadding(Design.dp(this,12),Design.dp(this,10),Design.dp(this,12),Design.dp(this,10));field.setMinHeight(Design.dp(this,48));field.setContentDescription(title);field.setInputType(InputType.TYPE_CLASS_TEXT|(password?InputType.TYPE_TEXT_VARIATION_PASSWORD:InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS));field.setText(value);body.addView(field,new LinearLayout.LayoutParams(-1,-2));return field;}
    private void readFields(){if(draft==null||name==null)return;draft=new AutomationRule(draft.id,name.getText().toString(),draft.event,draft.transport,enabled!=null&&enabled.isChecked(),draft.revision,destination.getText().toString().trim(),topic==null?"":topic.getText().toString(),username==null?"":username.getText().toString(),secret==null?"":secret.getText().toString());}
    private void save(){if(busy)return;readFields();try{draft.validate();}catch(Exception e){failure=e.getMessage();editor();return;}AutomationRule copy=draft;busy=true;failure="";editor();Automations.io.execute(()->{String issue="";try(AutomationStore store=new AutomationStore(this)){store.save(copy);Automations.schedule(this,store);}catch(Exception e){issue=e instanceof IllegalArgumentException||e instanceof IllegalStateException?e.getMessage():"Rule could not be saved. Check free space and retry.";}String error=issue;handler.post(()->{busy=false;if(isDestroyed())return;if(error.isEmpty())list();else{failure=error;editor();}});});}
    private void test(){if(busy)return;readFields();new android.app.AlertDialog.Builder(this).setTitle("Send saved rule’s test event?").setMessage("This sends a real event to the saved destination and can trigger its actions. Unsaved changes are not used.").setNegativeButton("Cancel",null).setPositiveButton("Send test",(dialog,which)->{String id=draft.id;Automations.io.execute(()->{String issue="Test event queued";try(AutomationStore store=new AutomationStore(this)){AutomationRule saved=store.rule(id);if(saved==null||!saved.enabled)issue="Enable and save this rule before sending a test.";else{store.enqueue(AutomationEvent.occurrence(saved.event,UUID.randomUUID().toString(),System.currentTimeMillis(),true),id);Automations.schedule(this,store);}}catch(Exception e){issue="Test event could not be queued.";}String result=issue;handler.post(()->{if(!isDestroyed()){failure=result;editor();}});});}).show();}
    private void delete(){if(busy)return;String id=draft.id;new android.app.AlertDialog.Builder(this).setTitle("Delete rule?").setMessage("Queued attempts will be removed. An in-flight request may already have been sent.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->Automations.io.execute(()->{try(AutomationStore store=new AutomationStore(this)){store.delete(id);Automations.schedule(this,store);}handler.post(()->{if(!isDestroyed())list();});})).show();}
    static String eventLabel(AutomationEvent.Kind kind){return switch(kind){case TRACKING_STARTED->"When tracking starts";case TRACKING_STOPPED->"When tracking ends";case ALARM_DISMISSED->"When alarm dismissed";};}
    static String transportLabel(AutomationRule.Transport kind){return switch(kind){case INTENT->"Tasker / app";case WEBHOOK->"Webhook";case MQTT->"MQTT";};}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    @Override protected void onDestroy(){generation++;handler.removeCallbacksAndMessages(null);super.onDestroy();}
}
